#!/usr/bin/env python3
import numpy as np
import matplotlib.pyplot as plt

#plot IP and fft(IP)
def fftspec(data, time):
    spec = np.fft.fft(data)
    freq=np.fft.fftfreq(len(data),d=float(time[1])-float(time[0]))
    spec=abs(spec)[freq>0]
    freq=freq[freq>0]*1.0e5/3.0
    return spec, freq

def plot_std(name):
    time = []
    sig = []
    with open(name) as f:
        data = f.readlines()
        for i in data:
            s = i.split(' ')
            time.append(float(s[0]))
            sig.append(float(s[1].split('\\')[0]))
    return time, sig

time, sig = plot_std('signal_sum.out')
plt.plot(time, sig)
plt.xlabel('$\Delta\\tau$ in fs')
plt.ylabel('Signal')
plt.savefig('signal_out.png', dpi=600)
plt.show()
freq, spec = fftspec(sig, time)
np.savetxt('signal_fft.out', np.transpose([spec, freq]))

plt.xlabel('FFT $v$ in cm$^{-1}$')
plt.plot(spec, freq)
plt.savefig('signal_fft_out.png', dpi=600)
plt.show()
